program:
root = Page([shell])
shell = AppShell("Pulse", navGroups, "Subscription Analytics", [kpis, chartsSection, tableSection], userProfile)
navGroups = [navGroupMain, navGroupBilling]
navGroupMain = {id: "analytics", label: "Analytics", items: [navOverview, navSubscriptions, navCustomers]}
navOverview = {id: "overview", label: "Overview", icon: "layout-dashboard"}
navSubscriptions = {id: "subscriptions", label: "Subscriptions", icon: "credit-card"}
navCustomers = {id: "customers", label: "Customers", icon: "users"}
navGroupBilling = {id: "settings", label: "Administration", items: [navPlans, navSettings]}
navPlans = {id: "plans", label: "Pricing Plans", icon: "layers"}
navSettings = {id: "settings-item", label: "Settings", icon: "settings"}
userProfile = {name: "Sarah Lin", detail: "Growth Lead"}
kpis = MetricCards([mrrMetric, accountsMetric, conversionMetric, churnMetric], "mrr")
mrrMetric = {id: "mrr", label: "Monthly Recurring Revenue", value: "$64,280", trend: "+14.2% vs last month"}
accountsMetric = {id: "accounts", label: "Active Subscriptions", value: "1,842", description: "Across all tiers"}
conversionMetric = {id: "conversion", label: "Trial Conversion", value: "4.8%", trend: "+0.6% this cycle"}
churnMetric = {id: "churn", label: "Monthly Churn Rate", value: "1.9%", description: "-0.3% vs target"}
chartsSection = DashboardSection([chartCard], "Revenue Performance", "Historical monthly recurring revenue growth over the past two quarters")
chartCard = Card([chart], "MRR Trend (USD)", "May - Oct 2026")
chart = AreaChart(chartLabels, [revenueSeries], "Month", "Revenue ($k)")
chartLabels = ["May", "Jun", "Jul", "Aug", "Sep", "Oct"]
revenueSeries = Series("MRR ($k)", [48.2, 51.5, 54.0, 58.6, 61.2, 64.3])
tableSection = DashboardSection([customersTable], "Recent Customer Activity", "Latest plan activations and status changes", tableActions)
tableActions = Buttons([exportButton, filterButton])
exportButton = Button("Export CSV", null, "outline", "sm")
filterButton = Button("Add customer", null, "default", "sm")
customersTable = Table(tableColumns, tableRows, 5, {search:true,filterBy:["Status"],sort:true,pageSize:5})
tableColumns = [colCustomer, colPlan, colBilling, colAmount, colStatus]
colCustomer = TableColumn("Customer", "string")
colPlan = TableColumn("Plan", "string")
colBilling = TableColumn("Cycle", "string")
colAmount = TableColumn("Amount", "string")
colStatus = TableColumn("Status", "string")
tableRows = [row1, row2, row3, row4, row5]
row1 = ["Acrobatics Studio", "Scale", "Annual", "$4,800/yr", Badge("Active", "default")]
row2 = ["Beacon Labs", "Pro", "Monthly", "$290/mo", Badge("Active", "default")]
row3 = ["Cloudline Inc", "Enterprise", "Annual", "$12,000/yr", Badge("Active", "secondary")]
row4 = ["Delta Peak AI", "Pro", "Monthly", "$290/mo", Badge("Trial", "outline")]
row5 = ["Echo Media Co", "Starter", "Monthly", "$79/mo", Badge("Past Due", "destructive")]
